package br.radaraero.widget;
import android.app.*;import android.appwidget.*;import android.os.*;import android.content.*;import android.widget.*;import android.text.InputType;import org.json.*;
public class ConfigureActivity extends Activity {
 int widgetId; EditText lat,lon,url; Spinner radius; TextView notice;
 @Override public void onCreate(Bundle b){super.onCreate(b);setResult(RESULT_CANCELED);widgetId=getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,AppWidgetManager.INVALID_APPWIDGET_ID);
 LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(32,48,32,24);ScrollView scroll=new ScrollView(this);scroll.addView(box);setContentView(scroll);
 TextView title=new TextView(this);title.setText("Radar Aero · Widget Android");title.setTextSize(24);box.addView(title);notice=new TextView(this);notice.setText("Ponto fixo, sem rastreamento em segundo plano. Distâncias horizontais; altitude barométrica. A rede ADS-B pode não receber todos os aviões.");box.addView(notice);
 lat=field(box,"Latitude (-90 a 90)",true);lon=field(box,"Longitude (-180 a 180)",true);url=field(box,"Endereço HTTPS do Radar (opcional)",false);
 radius=new Spinner(this);radius.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"5 km","10 km","25 km","50 km"}));radius.setSelection(1);box.addView(radius);
 android.content.SharedPreferences prefs=getSharedPreferences("radar",0);String saved=prefs.getString("point",null);if(saved!=null)try{fill(new JSONObject(saved));}catch(Exception ignored){}
 Button imp=new Button(this);imp.setText("Importar ponto exportado pelo Radar");box.addView(imp);imp.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,7);});
 Button save=new Button(this);save.setText("Salvar ponto e atualizar widgets");box.addView(save);save.setOnClickListener(v->save());TextView help=new TextView(this);help.setText("Depois de instalar: pressione a tela inicial → Widgets → Radar Aero. Todos os widgets usam este mesmo ponto. Atualização automática solicitada a cada 30 minutos, sujeita ao Android; toque em Atualizar para consultar. Não usar para navegação aérea. Dados: adsb.lol · ODbL.");box.addView(help);
 }
 EditText field(LinearLayout box,String hint,boolean number){EditText e=new EditText(this);e.setHint(hint);e.setSingleLine(true);e.setInputType(number?InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL|InputType.TYPE_NUMBER_FLAG_SIGNED:InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI);box.addView(e);return e;}
 static byte[] readLimited(java.io.InputStream in,int max)throws java.io.IOException{java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>max)throw new java.io.IOException("Arquivo muito grande");out.write(buffer,0,n);}return out.toByteArray();}
 void fill(JSONObject p)throws Exception{lat.setText(p.getString("lat"));lon.setText(p.getString("lon"));url.setText(p.optString("radarUrl",""));int r=p.optInt("radiusKm",10);radius.setSelection(r==5?0:r==25?2:r==50?3:1);}
 void save(){try{double a=Double.parseDouble(lat.getText().toString()),o=Double.parseDouble(lon.getText().toString());if(!Double.isFinite(a)||!Double.isFinite(o)||Math.abs(a)>90||Math.abs(o)>180)throw new Exception();String link=url.getText().toString().trim();if(!link.isEmpty()){android.net.Uri u=android.net.Uri.parse(link);if(!"https".equals(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null)throw new Exception();}JSONObject p=new JSONObject();p.put("version",1);p.put("lat",a);p.put("lon",o);p.put("radiusKm",new int[]{5,10,25,50}[radius.getSelectedItemPosition()]);p.put("radarUrl",link);getSharedPreferences("radar",0).edit().putString("point",p.toString()).remove("snapshot").apply();RadarWidget.drawAll(this,"Consultando…");RefreshJob.schedule(this);if(widgetId!=AppWidgetManager.INVALID_APPWIDGET_ID){Intent result=new Intent();result.putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,widgetId);setResult(RESULT_OK,result);finish();}else notice.setText("Ponto salvo! Adicione o widget na tela inicial.");}catch(Exception e){notice.setText("Confira as coordenadas e use um endereço HTTPS válido ou deixe o endereço vazio.");}}
 @Override public void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==7&&result==RESULT_OK&&data!=null)try(java.io.InputStream in=getContentResolver().openInputStream(data.getData())){byte[] bytes=readLimited(in,8192);if(bytes.length>8192)throw new Exception();JSONObject p=new JSONObject(new String(bytes,java.nio.charset.StandardCharsets.UTF_8));if(p.optInt("version")!=1)throw new Exception();fill(p);notice.setText("Ponto importado. Confira e toque em Salvar.");}catch(Exception e){notice.setText("Não foi possível importar esse arquivo.");}}
}

